local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
---@type SDKService
local SDKService = import('Game.Entry.SDKService')

local ItemLuaPath = "Game.UI.Common.PrimaryCurrencyBuyItem"

--- from: Assets/BundleResources/Prefabs/Common/SecondCurrencyPopUp2.prefab > name: SecondCurrencyPopUp2
---@class CommonPrimaryCurrencyBuyPopup
---@field Env                           	CommonPrimaryCurrencyBuyPopup           
---@field controller                    	Engine.UI.UILuaDialog                   
---@field BtnClose                      	UnityEngine.RectTransform               	@ 0    
