---@field SubText                       	UnityEngine.RectTransform               	@ 12   
local CommonPrimaryCurrencyBuyPopup = Class("CommonPrimaryCurrencyBuyPopup")


---@class CommonPrimaryCurrencyBuyPopup.InputData
---@field needNum number
---@field payedCallback fun(isSuccess:boolean)  购买成功则为true

function CommonPrimaryCurrencyBuyPopup:__init()
    ---@type CommonPrimaryCurrencyBuyPopup.InputData
    self.data = {}
    
    self.events = {}
    self.events[Constants.EventNames.EVENT_SDK] = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
end

function CommonPrimaryCurrencyBuyPopup:__delete()
    self.controller = nil
    for k, v in pairs(self.events) do
        Events.RemoveListener(k, v)
    end
end

function CommonPrimaryCurrencyBuyPopup:OnInitialize()
    local initParams = self.controller.Argument.parameters or {}
    self.data = initParams
    ---@type OverseaStoreHomeDojo.Product[]
    self.products = checkTable(OverseaStoreMgr:GetPrimaryCurrencyData())
    if #self.products == 0 then
        self.serverBack = false
        return CoWaitDo(function()
            OverseaStoreMgr:GetStoreComponent():RequestKrDiamondData(function()
                self.serverBack = true
                ---@type OverseaStoreHomeDojo.Product[]
                self.products = OverseaStoreMgr:GetPrimaryCurrencyData()
                self:RefreshUI()
            end)
            
            while not self.serverBack do
                CoYield()
            end
        end)
    else
        self:RefreshUI()    
    end
end

function CommonPrimaryCurrencyBuyPopup:Awake()
    SetButtonAction(self.BtnClose, Bind(self,self.OnClose))
    
    SetButtonAction(self.BtnMore, function()
        CfUtils.SetActive(self.SpecificationGroup, not self.SpecificationGroup.gameObject.activeSelf)
    end)
    
    SetButtonAction(self.BtnConfirm, function()
        self:OnItemClick(self.recommendIndex)
    end)
    
    CfUtils.SetActive(self.SpecificationGroup,false)
end

function CommonPrimaryCurrencyBuyPopup:RefreshUI()
    self.recommendIndex = 1
    local ownNum = GoodsUtils.GetThingNo(Constants.Currency.PayDiamondId)
    local needPayNum = self.data.needNum - ownNum
    for i, v in ipairs(self.products) do
        if v.num >= needPayNum then
            self.recommendIndex = i
            break
        end
    end
    local recommendProduct = checkTable(self.products[self.recommendIndex])
    local windowsPriceId =  CfUtils.GetWindowsPriceId(recommendProduct)
    CfUtils.FillText(self.TxtConfirm,CfUtils.GetCustomDisplayPrice(windowsPriceId,recommendProduct.channelProductId,30))
    CfUtils.FillText(self.MainText,localize("当前拥有：_num2_虹晶 ，还差：_num3_虹晶完成购买",{_num2_ = ownNum, _num3_ = needPayNum}))
    CfUtils.FillText(self.SubText,localize("[给您推荐了_num_虹晶规格]", { _num_ = checkNumber(recommendProduct.num)}))
    
    UICommonUtils.FillCommonGoodsListLight(self.CommonGoodsListLight,
            {{ goodsId = recommendProduct.icon, goodsNum = recommendProduct.num }},false, false, true, false, false)
    
    self:RefreshList()
end

function CommonPrimaryCurrencyBuyPopup:RefreshList()
    for i, v in ipairs(self.products) do
        local cell = self.SpecificationGroup:Find("BtnSpecificationChargeItem" .. i)
        if isNotNull(cell) then
            ---@type PrimaryCurrencyBuyItem
            local cellScr = CfUtils.GetLuaScr(cell.gameObject, ItemLuaPath)
            if not isNull(cellScr) then
                cellScr:RefreshData({
                    index = i,
                    select = i == self.recommendIndex,
                    product = v
                }, Bind(self,self.OnItemClick))
            end
        end
    end
end

function CommonPrimaryCurrencyBuyPopup:OnItemClick(index)
    local product = self.products[index]
    if product == nil then
        print('商品不存在')
        return
    end
    SDKService:GetInstance():PayMoney({
        productId = product.productId,
        channelProductId = product.channelProductId,
        productDesc = product.payPoint .. localize("虹晶"),
        payAmount = checkNumber(product.price),
        data = product
    })
end

function CommonPrimaryCurrencyBuyPopup:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        self.paySuccess = true
        self:OnClose()
    end
end

function CommonPrimaryCurrencyBuyPopup:OnClose()
    self.controller:Close()
    if self.data.payedCallback then
        self.data.payedCallback(checkBool(self.paySuccess))
    end
end

function CommonPrimaryCurrencyBuyPopup:OnFinalize()
    self:Delete()
end


return CommonPrimaryCurrencyBuyPopup